import { useEffect } from 'react'
import '../styles/modal.css'
import CloseIcon from '../assets/close.png'

interface Props {
    show: boolean,
    setShow: (show: boolean) => void
}

const Modal = (props: Props) => {

    if (props.show) {
        return (
            <div className="modal-container">
                <div className='modal' id='modal'>
                    <div className='close-modal'>
                        <img src={CloseIcon} height={18} alt="Close" className='close-icon' onClick={() => props.setShow(false)} />
                    </div>
                    <div className='rules'>
                        <div className='modal-title'>COMMENT JOUER</div>
                        <div className='text'>Le but du jeu est de trouver le prénom du mathématicien dont le nom de famille est donné.</div>
                        <div className='text'>Vous avez 6 essais, et un score vous est donné à chacune de vos propositions.</div>
                        <div className='text'>Ce score est basé selon la distance de Levenshtein, calculé par rapport au nombre de substitions de lettres à executer pour trouver la solution.</div>
                    </div>
                </div>
            </div>
        )
    }
    return null;
}

export default Modal;